import type { ActionFunctionArgs } from "react-router";
import { authenticate } from "../shopify.server";
import db from "../db.server";

// ─── Type guards ──────────────────────────────────────────────────────────────

interface CustomerPayload {
  customer: {
    id: number;
    email: string;
    phone?: string;
  };
  orders_requested?: Array<{ id: number }>;
}

interface ShopRedactPayload {
  shop_id: number;
  shop_domain: string;
}

function isCustomerPayload(payload: unknown): payload is CustomerPayload {
  return (
    typeof payload === "object" &&
    payload !== null &&
    "customer" in payload &&
    typeof (payload as Record<string, unknown>).customer === "object"
  );
}

function isShopRedactPayload(payload: unknown): payload is ShopRedactPayload {
  return (
    typeof payload === "object" &&
    payload !== null &&
    "shop_id" in payload &&
    "shop_domain" in payload
  );
}

// ─── CUSTOMERS_DATA_REQUEST handler ──────────────────────────────────────────
// Shopify sends this when a customer requests a copy of their data.
// We must acknowledge receipt — no deletion required.
// In production, email the merchant with a summary of data held.
async function handleCustomersDataRequest(
  shop: string,
  payload: unknown,
): Promise<void> {
  if (!isCustomerPayload(payload)) {
    console.warn(
      `[GDPR][CUSTOMERS_DATA_REQUEST] Unexpected payload shape for shop ${shop}`,
    );
    return;
  }

  const { customer, orders_requested } = payload;

  // Count what data we hold so the log is meaningful
  const [responseCount, analyticsCount] = await Promise.all([
    db.quizResponse.count({
      where: { shop, email: customer.email },
    }),
    db.analyticsEvent.count({
      where: { shop },
    }),
  ]);

  console.info(
    `[GDPR][CUSTOMERS_DATA_REQUEST] shop=${shop} customerId=${customer.id} ` +
      `email=${customer.email} ` +
      `quizResponses=${responseCount} analyticsEvents=${analyticsCount} ` +
      `ordersRequested=${orders_requested?.length ?? 0}`,
  );

  // TODO (production): fire an email to the merchant with the data summary
  // and a link to download the customer's quiz response history.
}

// ─── CUSTOMERS_REDACT handler ─────────────────────────────────────────────────
// Shopify sends this when Shopify has completed a customer erasure request.
// We must delete or anonymise all PII for that customer.
async function handleCustomersRedact(
  shop: string,
  payload: unknown,
): Promise<void> {
  if (!isCustomerPayload(payload)) {
    console.warn(
      `[GDPR][CUSTOMERS_REDACT] Unexpected payload shape for shop ${shop}`,
    );
    return;
  }

  const { customer } = payload;
  const email = customer.email;

  // Nullify email on all quiz responses — keep aggregate data intact
  const { count: responsesRedacted } = await db.quizResponse.updateMany({
    where: { shop, email },
    data: { email: null },
  });

  console.info(
    `[GDPR][CUSTOMERS_REDACT] shop=${shop} customerId=${customer.id} ` +
      `email=${email} responsesRedacted=${responsesRedacted}`,
  );
}

// ─── SHOP_REDACT handler ──────────────────────────────────────────────────────
// Shopify sends this ~48 hours after a merchant uninstalls the app.
// We must permanently delete ALL data for that shop.
// This runs after app/uninstalled has already cleaned sessions and cancelled
// subscriptions — here we erase the full data footprint.
async function handleShopRedact(shop: string, payload: unknown): Promise<void> {
  if (!isShopRedactPayload(payload)) {
    console.warn(
      `[GDPR][SHOP_REDACT] Unexpected payload shape for shop ${shop}`,
    );
  }

  // Count existing records for idempotency logging
  const quizCount = await db.quiz.count({ where: { shop } });

  if (quizCount === 0) {
    // Check remaining models in case quizzes were already erased
    const [productMappingCount, widgetCount, integrationCount] =
      await Promise.all([
        db.productMapping.count({ where: { shop } }),
        db.widgetConfig.count({ where: { shop } }),
        db.emailIntegration.count({ where: { shop } }),
      ]);

    const totalRemaining =
      productMappingCount + widgetCount + integrationCount;

    if (totalRemaining === 0) {
      console.info(
        `[GDPR][SHOP_REDACT] shop=${shop} — no data found, skipping (already redacted)`,
      );
      return;
    }
  }

  // Delete in dependency order to respect foreign-key constraints.
  // Quiz deletion cascades to: Question → Answer, ResultPage, QuizResponse,
  // and AnalyticsEvent (all have onDelete: Cascade).
  // Remaining models are shop-scoped root records.
  const [quizResult, productMappingResult, subscriptionResult] =
    await db.$transaction([
      db.quiz.deleteMany({ where: { shop } }),
      db.productMapping.deleteMany({ where: { shop } }),
      db.subscription.deleteMany({ where: { shop } }),
    ]);

  // WidgetConfig and EmailIntegration are independent — delete outside the
  // same transaction to avoid lock contention on large datasets.
  const [widgetResult, integrationResult, templateResult, sessionResult] =
    await Promise.all([
      db.widgetConfig.deleteMany({ where: { shop } }),
      db.emailIntegration.deleteMany({ where: { shop } }),
      // Only delete merchant-specific templates (isGlobal = false, shop = shop)
      db.quizTemplate.deleteMany({ where: { shop, isGlobal: false } }),
      // Remove any lingering sessions (belt-and-suspenders; uninstall webhook
      // should have done this already)
      db.session.deleteMany({ where: { shop } }),
    ]);

  console.info(
    `[GDPR][SHOP_REDACT] shop=${shop} — full erasure complete. ` +
      `quizzes=${quizResult.count} productMappings=${productMappingResult.count} ` +
      `subscriptions=${subscriptionResult.count} widgetConfigs=${widgetResult.count} ` +
      `emailIntegrations=${integrationResult.count} ` +
      `shopTemplates=${templateResult.count} sessions=${sessionResult.count}`,
  );
}

// ─── Route action ─────────────────────────────────────────────────────────────

export const action = async ({ request }: ActionFunctionArgs) => {
  const { topic, shop, payload } = await authenticate.webhook(request);

  console.info(`[Webhook] topic=${topic} shop=${shop}`);

  // Every case is wrapped individually so that an error in one handler never
  // prevents us from returning 200. Shopify will deactivate the webhook
  // endpoint if it repeatedly receives non-200 responses.
  switch (topic) {
    case "CUSTOMERS_DATA_REQUEST": {
      try {
        await handleCustomersDataRequest(shop, payload);
      } catch (error) {
        console.error(
          `[GDPR][CUSTOMERS_DATA_REQUEST] Handler error for shop ${shop}:`,
          error,
        );
      }
      break;
    }

    case "CUSTOMERS_REDACT": {
      try {
        await handleCustomersRedact(shop, payload);
      } catch (error) {
        console.error(
          `[GDPR][CUSTOMERS_REDACT] Handler error for shop ${shop}:`,
          error,
        );
      }
      break;
    }

    case "SHOP_REDACT": {
      try {
        await handleShopRedact(shop, payload);
      } catch (error) {
        console.error(
          `[GDPR][SHOP_REDACT] Handler error for shop ${shop}:`,
          error,
        );
        // Still return 200 — Shopify sends SHOP_REDACT only once (or a small
        // number of times). A retry loop does not help if the error is
        // permanent (e.g. shop data already gone). Log for manual review.
      }
      break;
    }

    default: {
      console.warn(`[Webhook] Unhandled topic=${topic} shop=${shop}`);
      break;
    }
  }

  // ALWAYS return 200. Non-200 causes Shopify to retry and eventually
  // deactivate the webhook subscription.
  return new Response(null, { status: 200 });
};

import type { ActionFunctionArgs } from "react-router";
import { authenticate } from "../shopify.server";
import db from "../db.server";

// ─── Route action ─────────────────────────────────────────────────────────────
// Shopify fires app/uninstalled immediately when the merchant removes the app.
// This handler runs BEFORE the 48-hour SHOP_REDACT grace period.
//
// Responsibility split:
//   app/uninstalled  → cancel subscription, delete sessions (immediate cleanup)
//   SHOP_REDACT      → delete all PII and quiz data (48h later)
//
// This split means billing records persist for reconciliation but sessions are
// invalidated instantly so re-auth cannot succeed with stale tokens.

export const action = async ({ request }: ActionFunctionArgs) => {
  const { shop, session, topic } = await authenticate.webhook(request);

  console.info(`[Webhook] topic=${topic} shop=${shop}`);

  // ── 1. Cancel active subscription ──────────────────────────────────────────
  // Keep the Subscription row for billing history / grace period tracking.
  // Only transition statuses that are still "live".
  try {
    const updated = await db.subscription.updateMany({
      where: {
        shop,
        status: { in: ["active", "trialing", "pending"] },
      },
      data: {
        status: "cancelled",
      },
    });

    if (updated.count > 0) {
      console.info(
        `[app/uninstalled] shop=${shop} cancelled ${updated.count} subscription(s)`,
      );
    } else {
      console.info(
        `[app/uninstalled] shop=${shop} — no active subscriptions to cancel`,
      );
    }
  } catch (error) {
    console.error(
      `[app/uninstalled] Failed to cancel subscription for shop ${shop}:`,
      error,
    );
  }

  // ── 2. Delete sessions ─────────────────────────────────────────────────────
  // The webhook may fire multiple times (Shopify retry) and the session may
  // already be gone. Guard with a count check to make the delete idempotent.
  try {
    if (session) {
      // Fast path: we know the exact session from the authenticated webhook
      const deleted = await db.session.deleteMany({ where: { shop } });
      console.info(
        `[app/uninstalled] shop=${shop} deleted ${deleted.count} session(s)`,
      );
    } else {
      // Slow path: webhook arrived after sessions were already deleted
      const sessionCount = await db.session.count({ where: { shop } });
      if (sessionCount > 0) {
        const deleted = await db.session.deleteMany({ where: { shop } });
        console.info(
          `[app/uninstalled] shop=${shop} deleted ${deleted.count} lingering session(s)`,
        );
      } else {
        console.info(
          `[app/uninstalled] shop=${shop} — no sessions to delete (already gone)`,
        );
      }
    }
  } catch (error) {
    console.error(
      `[app/uninstalled] Failed to delete sessions for shop ${shop}:`,
      error,
    );
  }

  // ── 3. Pause / archive all active quizzes ─────────────────────────────────
  // Prevents the storefront widget from serving quiz data after uninstall,
  // without destroying data that SHOP_REDACT will clean up later.
  try {
    const paused = await db.quiz.updateMany({
      where: { shop, status: { in: ["active", "draft"] } },
      data: { status: "paused" },
    });

    if (paused.count > 0) {
      console.info(
        `[app/uninstalled] shop=${shop} paused ${paused.count} quiz(zes)`,
      );
    }
  } catch (error) {
    console.error(
      `[app/uninstalled] Failed to pause quizzes for shop ${shop}:`,
      error,
    );
  }

  console.info(
    `[app/uninstalled] shop=${shop} — uninstall handling complete. ` +
      `SHOP_REDACT will erase all data in ~48h.`,
  );

  // ALWAYS return 200. A non-200 causes Shopify to retry and log the
  // webhook as failed, which can affect the app's partner dashboard health score.
  return new Response(null, { status: 200 });
};

import type { ActionFunctionArgs } from "react-router";
import { authenticate } from "../shopify.server";
import db from "../db.server";

// ─── Payload shape ────────────────────────────────────────────────────────────

interface ScopesUpdatePayload {
  current: string[];
  previous: string[];
}

function isScopesUpdatePayload(
  payload: unknown,
): payload is ScopesUpdatePayload {
  return (
    typeof payload === "object" &&
    payload !== null &&
    "current" in payload &&
    Array.isArray((payload as Record<string, unknown>).current)
  );
}

// ─── Route action ─────────────────────────────────────────────────────────────
// Shopify fires app/scopes_update when the OAuth access scopes for the app
// change (e.g. the merchant grants additional permissions or the app requests
// new scopes during an update).
//
// We persist the updated scope string on the session record so that the
// Shopify SDK can correctly check permission coverage on subsequent requests.

export const action = async ({ request }: ActionFunctionArgs) => {
  const { payload, session, topic, shop } = await authenticate.webhook(request);

  console.info(`[Webhook] topic=${topic} shop=${shop}`);

  if (!isScopesUpdatePayload(payload)) {
    console.warn(
      `[app/scopes_update] Unexpected payload shape for shop ${shop}:`,
      payload,
    );
    // Still return 200 — a malformed payload is not retryable
    return new Response(null, { status: 200 });
  }

  const { current, previous } = payload;
  const currentScopeString = current.join(",");
  const previousScopeString = previous.join(",");

  console.info(
    `[app/scopes_update] shop=${shop} ` +
      `previous="${previousScopeString}" current="${currentScopeString}"`,
  );

  // Persist the new scope to the session so the SDK's permission checks
  // reflect the updated access level.
  if (session) {
    try {
      await db.session.update({
        where: { id: session.id },
        data: { scope: currentScopeString },
      });

      console.info(
        `[app/scopes_update] shop=${shop} session ${session.id} scope updated`,
      );
    } catch (error) {
      console.error(
        `[app/scopes_update] Failed to update session scope for shop ${shop}:`,
        error,
      );
      // Non-fatal: the session will be refreshed on the next OAuth flow.
      // Do not propagate — still return 200.
    }
  } else {
    // The session may already have been deleted (e.g. offline token flow with
    // a previously uninstalled shop). Log and move on.
    console.warn(
      `[app/scopes_update] shop=${shop} — no session found, scope not persisted`,
    );
  }

  return new Response(null, { status: 200 });
};

