194→      break;
195→    }
196→
197→    case "CUSTOMERS_REDACT": {
198→      try {
199→        await handleCustomersRedact(shop, payload);
200→      } catch (error) {
201→        console.error(
202→          `[GDPR][CUSTOMERS_REDACT] Handler error for shop ${shop}:`,
203→          error,
204→        );
205→      }
206→      break;
207→    }
208→
209→    case "SHOP_REDACT": {
210→      try {
211→        await handleShopRedact(shop, payload);
212→      } catch (error) {
213→        console.error(
214→          `[GDPR][SHOP_REDACT] Handler error for shop ${shop}:`,
215→          error,
216→        );
217→        // Still return 200 — Shopify sends SHOP_REDACT only once (or a small
218→        // number of times). A retry loop does not help if the error is
219→        // permanent (e.g. shop data already gone). Log for manual review.
220→      }
221→      break;
222→    }
223→
224→    default: {
225→      console.warn(`[Webhook] Unhandled topic=${topic} shop=${shop}`);
226→      break;
227→    }
228→  }
