  5→// ─── Route action ─────────────────────────────────────────────────────────────
  6→// Shopify fires app/uninstalled immediately when the merchant removes the app.
  7→// This handler runs BEFORE the 48-hour SHOP_REDACT grace period.
  8→//
  9→// Responsibility split:
 10→//   app/uninstalled  → cancel subscription, delete sessions (immediate cleanup)
 11→//   SHOP_REDACT      → delete all PII and quiz data (48h later)
 12→//
 13→// This split means billing records persist for reconciliation but sessions are
 14→// invalidated instantly so re-auth cannot succeed with stale tokens.
 15→
 16→export const action = async ({ request }: ActionFunctionArgs) => {
 17→  const { shop, session, topic } = await authenticate.webhook(request);
 18→
 19→  console.info(`[Webhook] topic=${topic} shop=${shop}`);
 20→
 21→  // ── 1. Cancel active subscription ──────────────────────────────────────────
 22→  // Keep the Subscription row for billing history / grace period tracking.
 23→  // Only transition statuses that are still "live".
 24→  try {
 25→    const updated = await db.subscription.updateMany({
 26→      where: {
 27→        shop,
 28→        status: { in: ["active", "trialing", "pending"] },
 29→      },
 30→      data: {
 31→        status: "cancelled",
 32→      },
 33→    });
 34→
 35→    if (updated.count > 0) {
 36→      console.info(
 37→        `[app/uninstalled] shop=${shop} cancelled ${updated.count} subscription(s)`,
 38→      );
 39→    } else {
 40→      console.info(
 41→        `[app/uninstalled] shop=${shop} — no active subscriptions to cancel`,
 42→      );
 43→    }
 44→  } catch (error) {
 45→    console.error(
 46→      `[app/uninstalled] Failed to cancel subscription for shop ${shop}:`,
 47→      error,
 48→    );
 49→  }
 50→
 51→  // ── 2. Delete sessions ─────────────────────────────────────────────────────
 52→  // The webhook may fire multiple times (Shopify retry) and the session may
 53→  // already be gone. Guard with a count check to make the delete idempotent.
 54→  try {
 55→    if (session) {
 56→      // Fast path: we know the exact session from the authenticated webhook
 57→      const deleted = await db.session.deleteMany({ where: { shop } });
 58→      console.info(
 59→        `[app/uninstalled] shop=${shop} deleted ${deleted.count} session(s)`,
 60→      );
 61→    } else {
 62→      // Slow path: webhook arrived after sessions were already deleted
 63→      const sessionCount = await db.session.count({ where: { shop } });
 64→      if (sessionCount > 0) {
 65→        const deleted = await db.session.deleteMany({ where: { shop } });
 66→        console.info(
 67→          `[app/uninstalled] shop=${shop} deleted ${deleted.count} lingering session(s)`,
 68→        );
 69→      } else {
 70→        console.info(
 71→          `[app/uninstalled] shop=${shop} — no sessions to delete (already gone)`,
 72→        );
 73→      }
 74→    }
 75→  } catch (error) {
 76→    console.error(
 77→      `[app/uninstalled] Failed to delete sessions for shop ${shop}:`,
 78→      error,
 79→    );
 80→  }
 81→
 82→  // ── 3. Pause / archive all active quizzes ─────────────────────────────────
 83→  // Prevents the storefront widget from serving quiz data after uninstall,
 84→  // without destroying data that SHOP_REDACT will clean up later.
 85→  try {
 86→    const paused = await db.quiz.updateMany({
 87→      where: { shop, status: { in: ["active", "draft"] } },
 88→      data: { status: "paused" },
 89→    });
 90→
 91→    if (paused.count > 0) {
 92→      console.info(
 93→        `[app/uninstalled] shop=${shop} paused ${paused.count} quiz(zes)`,
 94→      );
 95→    }
 96→  } catch (error) {
 97→    console.error(
 98→      `[app/uninstalled] Failed to pause quizzes for shop ${shop}:`,
 99→      error,
100→    );
101→  }
102→
103→  console.info(
104→    `[app/uninstalled] shop=${shop} — uninstall handling complete. ` +
105→      `SHOP_REDACT will erase all data in ~48h.`,
106→  );
107→
108→  // ALWAYS return 200. A non-200 causes Shopify to retry and log the
109→  // webhook as failed, which can affect the app's partner dashboard health score.
110→  return new Response(null, { status: 200 });
111→};
