 5→// ─── Payload shape ────────────────────────────────────────────────────────────
 6→
 7→interface ScopesUpdatePayload {
 8→  current: string[];
 9→  previous: string[];
10→}
11→
12→function isScopesUpdatePayload(
13→  payload: unknown,
14→): payload is ScopesUpdatePayload {
15→  return (
16→    typeof payload === "object" &&
17→    payload !== null &&
18→    "current" in payload &&
19→    Array.isArray((payload as Record<string, unknown>).current)
20→  );
21→}
