23→// ─── Route action ─────────────────────────────────────────────────────────────
24→// Shopify fires app/scopes_update when the OAuth access scopes for the app
25→// change (e.g. the merchant grants additional permissions or the app requests
26→// new scopes during an update).
27→//
28→// We persist the updated scope string on the session record so that the
29→// Shopify SDK can correctly check permission coverage on subsequent requests.
30→
31→export const action = async ({ request }: ActionFunctionArgs) => {
32→  const { payload, session, topic, shop } = await authenticate.webhook(request);
33→
34→  console.info(`[Webhook] topic=${topic} shop=${shop}`);
35→
36→  if (!isScopesUpdatePayload(payload)) {
37→    console.warn(
38→      `[app/scopes_update] Unexpected payload shape for shop ${shop}:`,
39→      payload,
40→    );
41→    // Still return 200 — a malformed payload is not retryable
42→    return new Response(null, { status: 200 });
43→  }
44→
45→  const { current, previous } = payload;
46→  const currentScopeString = current.join(",");
47→  const previousScopeString = previous.join(",");
48→
49→  console.info(
50→    `[app/scopes_update] shop=${shop} ` +
51→      `previous="${previousScopeString}" current="${currentScopeString}"`,
52→  );
53→
54→  // Persist the new scope to the session so the SDK's permission checks
55→  // reflect the updated access level.
56→  if (session) {
57→    try {
58→      await db.session.update({
59→        where: { id: session.id },
60→        data: { scope: currentScopeString },
61→      });
62→
63→      console.info(
64→        `[app/scopes_update] shop=${shop} session ${session.id} scope updated`,
65→      );
66→    } catch (error) {
67→      console.error(
68→        `[app/scopes_update] Failed to update session scope for shop ${shop}:`,
69→        error,
70→      );
71→      // Non-fatal: the session will be refreshed on the next OAuth flow.
72→      // Do not propagate — still return 200.
73→    }
74→  } else {
75→    // The session may already have been deleted (e.g. offline token flow with
76→    // a previously uninstalled shop). Log and move on.
77→    console.warn(
78→      `[app/scopes_update] shop=${shop} — no session found, scope not persisted`,
79→    );
80→  }
81→
82→  return new Response(null, { status: 200 });
83→};
